package cn.mop.api;
import cn.mop.domain.*;
import cn.mop.domain.manualincident.*;
import cn.mop.domain.manualincident.ManualIncidentRepository.*;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.node.*;
import org.junit.jupiter.api.*;
import org.springframework.mock.web.MockHttpServletRequest;
import java.nio.charset.StandardCharsets;
import java.time.Instant;
import java.util.*;
import java.util.function.Supplier;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
class ManualIncidentControllerTest {
    static final String ACTOR="55000000-0000-4000-8000-000000000001",TENANT="55000000-0000-4000-8000-000000000011",ASSET="55000000-0000-4000-8000-000000000021",ID="55000000-0000-4000-8000-000000000031";
    ObjectMapper mapper=new ObjectMapper();PlatformRepository platform;ManualIncidentRepository incidents;ManualIncidentController controller;
    @BeforeEach void setup(){platform=mock(PlatformRepository.class);incidents=mock(ManualIncidentRepository.class);controller=new ManualIncidentController(platform,incidents,mapper);role("msp");}
    void role(String role){when(platform.membership(ACTOR,TENANT)).thenReturn(Optional.of(new Membership(ACTOR,TENANT,role,7,true)));}
    MockHttpServletRequest request(String method){var r=new MockHttpServletRequest(method,"/api/v1/manual-incidents");r.setUserPrincipal(()->ACTOR);r.getSession().setAttribute("mop.tenant_id",TENANT);r.setAttribute("mop.trace_id","synthetic-trace");r.addHeader("Idempotency-Key","synthetic-request");return r;}
    Access access(){return new Access(ACTOR,TENANT,7,"synthetic-trace");}
    ObjectNode input(){return mapper.createObjectNode().put("title","  原始登记😀  ").put("severity","warning").put("asset_id",ASSET).put("expected_asset_version",1);}
    ManualIncident fact(){return new ManualIncident("  原始登记😀  ",ManualIncident.Severity.WARNING,ASSET,1);}
    Entry entry(){return new Entry(ID,TENANT,fact(),"合成资产",ACTOR,Instant.parse("2026-10-03T00:00:00Z"));}
    Map<?,?> data(Object value){return (Map<?,?>)((Map<?,?>)value).get("data");}
    @Test void trustedScopeFreshAssetGuardAndTransactionPreserveRawFacts(){when(platform.idempotentAuthorized(any(),any(),any(),any(),any(),anyLong(),any(),any())).thenAnswer(c->{((Runnable)c.getArgument(6)).run();return ((Supplier<?>)c.getArgument(7)).get();});when(incidents.create(access(),fact())).thenReturn(entry());var value=data(controller.write(input(),request("POST")));assertEquals(ID,value.get("id"));assertEquals("  原始登记😀  ",value.get("title"));assertEquals("MANUAL",value.get("source_state"));assertEquals("REGISTERED_ONLY",value.get("registration_status"));assertEquals(false,value.get("monitoring_recovery_applicable"));assertEquals(false,value.get("ticket_automatically_created"));for(String field:List.of("monitor_state","disposition_state","ticket_priority","observed_at","recovered_at"))assertNull(value.get(field));var order=inOrder(incidents);order.verify(incidents).authorizeCurrentAsset(access(),ASSET);order.verify(incidents).create(access(),fact());}
    @Test void internalRoleCapabilitiesAreExplicitAndCustomerUnknownDenied(){for(String role:List.of("msp","padmin")){role(role);when(incidents.get(access(),ID)).thenReturn(entry());assertEquals(ID,data(controller.get(ID,request("GET"))).get("id"));assertTrue(Capabilities.forRole(role).contains("manual_incidents:write"));}clearInvocations(incidents);for(String role:List.of("viewer","tadmin","unknown")){role(role);assertEquals(403,assertThrows(DomainException.class,()->controller.get(ID,request("GET"))).status);assertEquals(403,assertThrows(DomainException.class,()->controller.write(input(),request("POST"))).status);}verifyNoInteractions(incidents);}
    @Test void missingExpiredOrMalformedSessionFailsBeforeRepository(){for(Object tenant:List.of(5,"")){var r=request("GET");r.getSession().setAttribute("mop.tenant_id",tenant);assertEquals(401,assertThrows(DomainException.class,()->controller.list(r)).status);}var anonymous=new MockHttpServletRequest();assertEquals(401,assertThrows(DomainException.class,()->controller.list(anonymous)).status);when(platform.membership(ACTOR,TENANT)).thenReturn(Optional.empty());assertEquals(401,assertThrows(DomainException.class,()->controller.list(request("GET"))).status);verifyNoInteractions(incidents);}
    @Test void missingExtraAndClaimedStateFieldsAreRejected(){for(String field:List.of("title","severity","asset_id","expected_asset_version")){var b=input();b.remove(field);assertEquals(400,assertThrows(DomainException.class,()->controller.write(b,request("POST"))).status);}for(String field:List.of("tenant_id","actor_id","source_state","registration_status","monitor_state","disposition_state","ticket_priority","observed_at","recovered_at","asset_name_at_registration"))assertEquals(400,assertThrows(DomainException.class,()->controller.write(input().put(field,"forged"),request("POST"))).status);verifyNoInteractions(incidents);}
    @Test void severityVersionAndUnicodeLimitsNeverDefault(){for(String severity:List.of("none","unknown","NORMAL",""))assertEquals(400,assertThrows(DomainException.class,()->controller.write(input().put("severity",severity),request("POST"))).status);for(JsonNode version:List.of(NullNode.instance,TextNode.valueOf("1"),IntNode.valueOf(0),DoubleNode.valueOf(1.5),LongNode.valueOf(9007199254740992L)))assertEquals(400,assertThrows(DomainException.class,()->controller.write(input().set("expected_asset_version",version),request("POST"))).status);for(String title:List.of(" \ufeff\u3000","x\n","😀".repeat(201),"\ud800"))assertEquals(400,assertThrows(DomainException.class,()->controller.write(input().put("title",title),request("POST"))).status);verifyNoInteractions(incidents);}
    @Test void strictParserRejectsDuplicatesTrailingDepthInvalidJsonAndOversize()throws Exception{for(String body:List.of("{\"title\":\"a\",\"title\":\"b\"}","{} {}","[[[1]]]","{", " ".repeat(8193))){var r=request("POST");r.setContent(body.getBytes(StandardCharsets.UTF_8));assertEquals(400,assertThrows(DomainException.class,()->ManualIncidentController.body(r)).status);}var b=input().put("title","😀".repeat(200));var r=request("POST");r.setContent(mapper.writeValueAsBytes(b));assertEquals(b,ManualIncidentController.body(r));}
    @Test void readPagesUseBoundedLimitAndNeverInvokeCommand(){when(incidents.list(access(),16,null,null)).thenReturn(List.of(entry()));var result=data(controller.list(request("GET")));assertEquals(false,result.get("has_more"));assertNull(result.get("next_before_registered_at"));assertEquals("CURRENT_REQUEST_SNAPSHOT_ONLY",result.get("pagination_consistency"));verify(platform,never()).idempotentAuthorized(any(),any(),any(),any(),any(),anyLong(),any(),any());}
    @Test void queryWhitelistDuplicateAndPairedCursorAreStrict(){for(String field:List.of("tenant_id","severity","asset_id")){var r=request("GET");r.addParameter(field,"forged");assertEquals(400,assertThrows(DomainException.class,()->controller.list(r)).status);}var duplicate=request("GET");duplicate.addParameter("page_size",new String[]{"10","15"});assertEquals(400,assertThrows(DomainException.class,()->controller.list(duplicate)).status);var partial=request("GET");partial.addParameter("before_id",ID);assertEquals(400,assertThrows(DomainException.class,()->controller.list(partial)).status);for(String size:List.of("0","101","1","15.0")){var r=request("GET");r.addParameter("page_size",size);assertEquals(400,assertThrows(DomainException.class,()->controller.list(r)).status);}verifyNoInteractions(incidents);}
    @Test void cachedReceiptRechecksAssetWithoutExecutingCreate(){when(platform.idempotentAuthorized(any(),any(),any(),any(),any(),anyLong(),any(),any())).thenAnswer(c->{((Runnable)c.getArgument(6)).run();return Map.of("original",true);});assertEquals(true,data(controller.write(input(),request("POST"))).get("original"));verify(incidents).authorizeCurrentAsset(access(),ASSET);verify(incidents,never()).create(any(),any());}
    @Test void hashIgnoresJsonObjectOrderButPreservesRawTitle(){List<String> hashes=new ArrayList<>();when(platform.idempotentAuthorized(any(),any(),any(),any(),any(),anyLong(),any(),any())).thenAnswer(c->{hashes.add(c.getArgument(4));return Map.of("receipt",true);});var b=input();controller.write(b,request("POST"));var reordered=mapper.createObjectNode().put("expected_asset_version",1).put("asset_id",ASSET).put("severity","warning").put("title",b.get("title").asText());controller.write(reordered,request("POST"));controller.write(input().put("title","原始登记😀"),request("POST"));assertEquals(hashes.get(0),hashes.get(1));assertNotEquals(hashes.get(0),hashes.get(2));}
    @Test void missingInvalidIdempotencyKeyAndWriteQueryOverridesCannotRun(){for(String key:List.of("","x y","a".repeat(129))){var r=request("POST");r.removeHeader("Idempotency-Key");r.addHeader("Idempotency-Key",key);assertEquals(400,assertThrows(DomainException.class,()->controller.write(input(),r)).status);}var missing=request("POST");missing.removeHeader("Idempotency-Key");assertEquals(400,assertThrows(DomainException.class,()->controller.write(input(),missing)).status);var query=request("POST");query.addParameter("tenant_id",TENANT);assertEquals(400,assertThrows(DomainException.class,()->controller.write(input(),query)).status);verifyNoInteractions(incidents);}
}
